def _block_network():
    import socket
    real_connect = socket.socket.connect
    real_create = socket.create_connection
    def guard_connect(self, address, *a, **k):
        host = address[0] if isinstance(address, tuple) else str(address)
        if host not in ('127.0.0.1', '::1', 'localhost'):
            raise RuntimeError(f'network blocked in tests: {address}')
        return real_connect(self, address, *a, **k)
    def guard_create(address, *a, **k):
        host = address[0] if isinstance(address, tuple) else str(address)
        if host not in ('127.0.0.1', '::1', 'localhost'):
            raise RuntimeError(f'network blocked in tests: {address}')
        return real_create(address, *a, **k)
    socket.socket.connect = guard_connect
    socket.create_connection = guard_create
    yield
    socket.socket.connect = real_connect
    socket.create_connection = real_create`. Also strip stored tokens before the client boots: in the session `client` fixture, after init_db(), run `from server.database import User` and for every user pop 'telegram_bot_token' from settings and commit (or delete the users rows with that key), so telegram_agent_loop() finds nothing to poll. Fix the misleading pin: replace conftest.py:8's OMNIROUTE_API_BASE line with a comment naming server/llm.py:429,606 and stating that the URL is hardcoded, or keep the env var and additionally monkeypatch the two literals in llm.py to http://localhost:9 via an autouse fixture.
